//! `ColorSpace::HSL` — hue / saturation / lightness triple.
//!
//! Mirrors the C++ aggregate: the constructor stores the three components
//! verbatim, with no normalisation, wrapping or clamping. Hue values such as
//! `370` or `-10` are kept exactly as given, which is observable through
//! [`hue_difference`](super::converter::ColorConverter::hue_difference).

/// A colour in the HSL model.
///
/// `h` is in degrees, `s` and `l` are fractions in `0..=1` by convention (but
/// never enforced, matching the C++ constructor).
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct Hsl {
    /// Hue, in degrees.
    pub h: f32,
    /// Saturation.
    pub s: f32,
    /// Lightness.
    pub l: f32,
}

impl Hsl {
    /// Builds an `HSL` from its three components, storing them as-is.
    pub fn new(h: f32, s: f32, l: f32) -> Self {
        Hsl { h, s, l }
    }
}

