//! `ColorSpace::ColorConverter` — conversions and metrics between colours.

use super::hsl::Hsl;

/// Namespace type holding the conversion/metric helpers.
pub struct ColorConverter;

impl ColorConverter {
    /// Angular distance between the hues of two colours, in degrees.
    ///
    /// The C++ implementation takes the plain absolute difference and folds it
    /// back over the circle only when it exceeds a half turn:
    ///
    /// ```text
    /// d = |h1 - h2|
    /// if d > 180 { d = 360 - d }
    /// ```
    ///
    /// Note that hues are *not* wrapped into `0..360` first, so the fold is a
    /// single subtraction rather than a true modular distance. Inputs outside
    /// one turn therefore fall through to negative results — `h1 = 0` against
    /// `h2 = 720` yields `-360`, and `370` against `0` yields `-10`. This
    /// quirk is reproduced deliberately.
    ///
    /// All arithmetic is done in `f32`, as in the original.
    pub fn hue_difference(a: &Hsl, b: &Hsl) -> f32 {
        let mut diff = (a.h - b.h).abs();
        if diff > 180.0f32 {
            diff = 360.0f32 - diff;
        }
        diff
    }
}

