//! `std::stof` re-implemented on top of C `strtof` semantics.
//!
//! `std::stof(s)` calls `strtof(s.c_str(), &end)` and then
//!
//! * throws `std::invalid_argument("stof")` when nothing could be converted
//!   (`end == begin`), and
//! * throws `std::out_of_range("stof")` when `strtof` set `ERANGE`.
//!
//! glibc's `strtof` accepts leading whitespace, an optional sign, then either
//! a decimal significand with an optional `e`-exponent, a C99 hex significand
//! (`0x1.8p1`) — the `p` exponent being optional in practice — or `inf` /
//! `infinity` / `nan` / `nan(chars)`, case-insensitively. Trailing garbage is
//! simply left unconsumed, so `"1.5abc"` parses as `1.5`.
//!
//! `ERANGE` is reported both for overflow (result would be infinite) and for
//! underflow, where glibc counts *any* subnormal result as underflow. That is
//! why `stof("1e-38")` throws even though `1e-38` is a representable float:
//! it is below `FLT_MIN`.

/// Which C++ exception `std::stof` would have thrown.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum StofError {
    /// No conversion could be performed.
    InvalidArgument,
    /// The value over- or underflowed `float`.
    OutOfRange,
}

impl StofError {
    /// Name of the corresponding C++ exception type.
    pub fn class_name(self) -> &'static str {
        match self {
            StofError::InvalidArgument => "std::invalid_argument",
            StofError::OutOfRange => "std::out_of_range",
        }
    }
}

/// `std::stof` behaviour, with the thrown exception surfaced as an `Err`.
pub fn try_stof(s: &str) -> Result<f32, StofError> {
    let b = s.as_bytes();
    let mut i = 0;

    while i < b.len() && is_c_space(b[i]) {
        i += 1;
    }

    let negative = match b.get(i) {
        Some(b'+') => {
            i += 1;
            false
        }
        Some(b'-') => {
            i += 1;
            true
        }
        _ => false,
    };

    // `inf` / `infinity` and `nan` / `nan(...)` never set ERANGE.
    if let Some(v) = parse_infinity(b, i) {
        return Ok(with_sign(v, negative));
    }
    if let Some(v) = parse_nan(b, i) {
        return Ok(with_sign(v, negative));
    }

    if starts_with_ci(b, i, b"0x") {
        // A lone `0x` with no hex digits is not a hex literal: `strtof` backs
        // off and converts just the leading `0`.
        if let Some(r) = parse_hex(b, i + 2, negative) {
            return r;
        }
        return Ok(with_sign(0.0, negative));
    }

    parse_decimal(b, i, negative).ok_or(StofError::InvalidArgument)?
}

/// `std::stof`, aborting the process the way an uncaught C++ exception does.
///
/// Reproduces the `terminate called after throwing ...` report on stderr and
/// the `SIGABRT` exit status.
pub fn stof(s: &str) -> f32 {
    match try_stof(s) {
        Ok(v) => v,
        Err(e) => {
            eprintln!(
                "terminate called after throwing an instance of '{}'",
                e.class_name()
            );
            eprintln!("  what():  stof");
            std::process::abort();
        }
    }
}

fn is_c_space(c: u8) -> bool {
    matches!(c, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

fn with_sign(v: f32, negative: bool) -> f32 {
    if negative {
        -v
    } else {
        v
    }
}

fn starts_with_ci(b: &[u8], at: usize, pat: &[u8]) -> bool {
    b.len() >= at + pat.len()
        && b[at..at + pat.len()]
            .iter()
            .zip(pat)
            .all(|(x, p)| x.to_ascii_lowercase() == *p)
}

fn parse_infinity(b: &[u8], at: usize) -> Option<f32> {
    if starts_with_ci(b, at, b"infinity") || starts_with_ci(b, at, b"inf") {
        Some(f32::INFINITY)
    } else {
        None
    }
}

fn parse_nan(b: &[u8], at: usize) -> Option<f32> {
    if starts_with_ci(b, at, b"nan") {
        Some(f32::NAN)
    } else {
        None
    }
}

/// Decimal significand with optional exponent.
///
/// Returns `None` when no digit is present at all; otherwise a `Result`
/// carrying the value or the `ERANGE` verdict.
fn parse_decimal(b: &[u8], at: usize, negative: bool) -> Option<Result<f32, StofError>> {
    let mut i = at;
    let mut int_digits = Vec::new();
    let mut frac_digits = Vec::new();

    while i < b.len() && b[i].is_ascii_digit() {
        int_digits.push(b[i]);
        i += 1;
    }
    if i < b.len() && b[i] == b'.' {
        let mut j = i + 1;
        while j < b.len() && b[j].is_ascii_digit() {
            frac_digits.push(b[j]);
            j += 1;
        }
        // A bare `.` still counts as part of the number once we have digits.
        if !int_digits.is_empty() || !frac_digits.is_empty() {
            i = j;
        }
    }
    if int_digits.is_empty() && frac_digits.is_empty() {
        return None;
    }

    // The exponent is only consumed when at least one digit follows it, so
    // `"1e"` converts as `1`.
    let mut exp_text = String::new();
    if i < b.len() && (b[i] | 0x20) == b'e' {
        let mut j = i + 1;
        let mut sign = "";
        match b.get(j) {
            Some(b'+') => j += 1,
            Some(b'-') => {
                sign = "-";
                j += 1;
            }
            _ => {}
        }
        let start = j;
        while j < b.len() && b[j].is_ascii_digit() {
            j += 1;
        }
        if j > start {
            exp_text = format!("{}{}", sign, std::str::from_utf8(&b[start..j]).unwrap());
        }
    }

    // Hand a canonical literal to the standard library's correctly-rounded
    // decimal-to-float conversion rather than re-deriving it.
    let mut canonical = String::new();
    canonical.push_str(if int_digits.is_empty() {
        "0"
    } else {
        std::str::from_utf8(&int_digits).unwrap()
    });
    canonical.push('.');
    canonical.push_str(if frac_digits.is_empty() {
        "0"
    } else {
        std::str::from_utf8(&frac_digits).unwrap()
    });
    if !exp_text.is_empty() {
        canonical.push('e');
        canonical.push_str(&exp_text);
    }

    let magnitude: f32 = canonical.parse().unwrap_or(f32::INFINITY);
    let any_nonzero = int_digits.iter().chain(&frac_digits).any(|d| *d != b'0');
    Some(check_range(magnitude, any_nonzero).map(|v| with_sign(v, negative)))
}

/// C99 hex significand: `0x` already consumed, `at` points at the digits.
///
/// Returns `None` when there is no hex digit, which makes the caller fall back
/// to converting the leading `0`.
fn parse_hex(b: &[u8], at: usize, negative: bool) -> Option<Result<f32, StofError>> {
    let mut i = at;
    // Significand accumulated as `mantissa * 2^bit_exp`, with `sticky`
    // recording digits dropped once `mantissa` ran out of room.
    let mut mantissa: u128 = 0;
    let mut bit_exp: i32 = 0;
    let mut sticky = false;
    let mut digit_count = 0usize;

    let mut push = |d: u32, mantissa: &mut u128, bit_exp: &mut i32, sticky: &mut bool| {
        if *mantissa < (1u128 << 120) {
            *mantissa = (*mantissa << 4) | d as u128;
        } else {
            // No room left: the digit only survives as a sticky bit, and the
            // radix point moves instead.
            if d != 0 {
                *sticky = true;
            }
            *bit_exp += 4;
        }
    };

    while i < b.len() && b[i].is_ascii_hexdigit() {
        push(hex_val(b[i]), &mut mantissa, &mut bit_exp, &mut sticky);
        digit_count += 1;
        i += 1;
    }
    let mut frac_digits = 0i32;
    if i < b.len() && b[i] == b'.' {
        let mut j = i + 1;
        while j < b.len() && b[j].is_ascii_hexdigit() {
            push(hex_val(b[j]), &mut mantissa, &mut bit_exp, &mut sticky);
            digit_count += 1;
            frac_digits += 1;
            j += 1;
        }
        if digit_count > 0 {
            i = j;
        }
    }
    if digit_count == 0 {
        return None;
    }
    bit_exp -= 4 * frac_digits;

    // Optional binary exponent, again only consumed when digits follow.
    if i < b.len() && (b[i] | 0x20) == b'p' {
        let mut j = i + 1;
        let mut neg_exp = false;
        match b.get(j) {
            Some(b'+') => j += 1,
            Some(b'-') => {
                neg_exp = true;
                j += 1;
            }
            _ => {}
        }
        let start = j;
        let mut value: i32 = 0;
        while j < b.len() && b[j].is_ascii_digit() {
            // Saturate: anything this large already over/underflows.
            value = value.saturating_mul(10).saturating_add((b[j] - b'0') as i32);
            value = value.min(1 << 24);
            j += 1;
        }
        if j > start {
            bit_exp = bit_exp.saturating_add(if neg_exp { -value } else { value });
        }
    }

    let magnitude = scale_to_f32(mantissa, sticky, bit_exp);
    Some(check_range(magnitude, mantissa != 0 || sticky).map(|v| with_sign(v, negative)))
}

fn hex_val(c: u8) -> u32 {
    (c as char).to_digit(16).unwrap()
}

/// Rounds `mantissa * 2^bit_exp` to `f32`, round-half-to-even, honouring a
/// sticky bit for significand digits that were dropped during accumulation.
fn scale_to_f32(mantissa: u128, sticky: bool, bit_exp: i32) -> f32 {
    if mantissa == 0 {
        return 0.0;
    }
    let msb = 127 - mantissa.leading_zeros() as i32;
    let value_exp = bit_exp as i64 + msb as i64;
    if value_exp > 128 {
        return f32::INFINITY;
    }
    if value_exp < -200 {
        return 0.0;
    }

    // Keep 24 significand bits, or fewer once the result goes subnormal
    // (`f32`'s smallest step is 2^-149).
    let target_exp = std::cmp::max(bit_exp as i64 + msb as i64 - 23, -149);
    let shift = target_exp - bit_exp as i64;
    let mut kept = mantissa;
    let mut exp = target_exp;

    if shift > 0 {
        if shift >= 128 {
            return 0.0;
        }
        let shift = shift as u32;
        let dropped = mantissa & ((1u128 << shift) - 1);
        let half = 1u128 << (shift - 1);
        kept = mantissa >> shift;
        let round_up = dropped > half || (dropped == half && (sticky || kept & 1 == 1));
        if round_up {
            kept += 1;
        }
    } else if shift < 0 {
        kept <<= (-shift) as u32;
    }

    // Rounding may have carried into a new binary digit.
    if kept >= 1u128 << 24 {
        kept >>= 1;
        exp += 1;
    }

    let scaled = (kept as f64) * pow2(exp as i32);
    scaled as f32
}

/// `2^e` as an `f64`, exact across the whole `f32` range.
fn pow2(e: i32) -> f64 {
    if e >= 0 {
        f64::from_bits(((1023 + e.min(1023)) as u64) << 52)
    } else if e >= -1022 {
        f64::from_bits(((1023 + e) as u64) << 52)
    } else {
        // Split the shift to stay clear of the subnormal f64 range.
        f64::from_bits((1u64) << 52) * pow2(e + 1022) * pow2(-1022)
    }
}

/// Applies glibc's `ERANGE` rules: infinite results overflow, and any nonzero
/// significand landing below `FLT_MIN` (subnormal or flushed to zero)
/// underflows.
fn check_range(magnitude: f32, any_nonzero: bool) -> Result<f32, StofError> {
    if magnitude.is_infinite() {
        return Err(StofError::OutOfRange);
    }
    if any_nonzero && magnitude.abs() < f32::MIN_POSITIVE {
        return Err(StofError::OutOfRange);
    }
    Ok(magnitude)
}

