//! `std::ostream`'s default floating-point formatting.
//!
//! With default flags (`defaultfloat`, `precision() == 6`), `operator<<` for a
//! floating-point type formats exactly like `printf("%g")` with precision 6:
//!
//! * the value is rounded to 6 significant decimal digits;
//! * with `X` the decimal exponent of the rounded value, the fixed form
//!   (`%.{5-X}f`) is used when `-4 <= X < 6`, and the scientific form
//!   (`%.5e`, exponent at least two digits) otherwise;
//! * because `#` is not set, trailing zeros in the fraction are removed, along
//!   with a then-empty decimal point.
//!
//! A `float` is promoted to `double` before formatting, and that promotion is
//! exact, so working in `f64` throughout matches the C++ output.
//!
//! Rounding to 6 digits must be round-half-to-even on exact ties — glibc
//! rounds `1.015625` to `1.01562`, not `1.01563`. Rust's `{:.5e}` uses the same
//! rule over the exact binary value, so it is used to produce the digits.

/// Formats `v` the way `std::cout << v` would with default stream flags.
pub fn format_default(v: f64) -> String {
    if v.is_nan() {
        // glibc keeps the sign of a NaN.
        return if v.is_sign_negative() { "-nan" } else { "nan" }.to_string();
    }
    if v.is_infinite() {
        return if v < 0.0 { "-inf" } else { "inf" }.to_string();
    }

    let sign = if v.is_sign_negative() { "-" } else { "" };
    let magnitude = v.abs();
    if magnitude == 0.0 {
        return format!("{}0", sign);
    }

    // "d.ddddde<exp>" — six significant digits, correctly rounded.
    let rendered = format!("{:.5e}", magnitude);
    let (mantissa, exponent) = rendered.split_once('e').expect("LowerExp always emits 'e'");
    let exponent: i32 = exponent.parse().expect("LowerExp emits a decimal exponent");
    let digits: Vec<u8> = mantissa.bytes().filter(|c| *c != b'.').collect();

    let body = if exponent < -4 || exponent >= 6 {
        scientific(&digits, exponent)
    } else {
        fixed(&digits, exponent)
    };
    format!("{}{}", sign, body)
}

/// `%.5e` with trailing fractional zeros stripped.
fn scientific(digits: &[u8], exponent: i32) -> String {
    let mut out = String::new();
    out.push(digits[0] as char);
    let fraction = trim_zeros(&digits[1..]);
    if !fraction.is_empty() {
        out.push('.');
        out.push_str(fraction);
    }
    // `printf` pads the exponent to at least two digits and always signs it.
    out.push('e');
    out.push(if exponent < 0 { '-' } else { '+' });
    out.push_str(&format!("{:02}", exponent.abs()));
    out
}

/// `%.{5-exponent}f` with trailing fractional zeros stripped.
fn fixed(digits: &[u8], exponent: i32) -> String {
    let mut out = String::new();
    if exponent >= 0 {
        // The exponent is < 6 here, so the split always lands inside `digits`.
        let split = exponent as usize + 1;
        out.push_str(std::str::from_utf8(&digits[..split]).unwrap());
        let fraction = trim_zeros(&digits[split..]);
        if !fraction.is_empty() {
            out.push('.');
            out.push_str(fraction);
        }
    } else {
        // -4 <= exponent < 0: pad with leading zeros after the point.
        let mut fraction = "0".repeat((-exponent - 1) as usize);
        fraction.push_str(std::str::from_utf8(digits).unwrap());
        // `digits[0]` is nonzero, so this can never trim everything away.
        out.push_str("0.");
        out.push_str(fraction.trim_end_matches('0'));
    }
    out
}

fn trim_zeros(digits: &[u8]) -> &str {
    std::str::from_utf8(digits).unwrap().trim_end_matches('0')
}

