// Port of tests/test13.cpp from the ColorSpace library.
//
// Library code lives under `src/`; the `#[path]` attributes keep this file
// buildable both with `cargo build --release` and with a bare `rustc test13.rs`.

#[path = "src/color/mod.rs"]
mod color;
#[path = "src/cxx/mod.rs"]
mod cxx;

use color::{ColorConverter, Hsl};
use cxx::{format_default, stof};

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let argc = args.len();

    let (mut h1, mut s1, mut l1) = (30.0f32, 0.6f32, 0.5f32);
    let (mut h2, mut s2, mut l2) = (210.0f32, 0.4f32, 0.7f32);

    // Five arguments set everything but `l2`, which needs a sixth.
    if argc > 5 {
        h1 = stof(&args[1]);
        s1 = stof(&args[2]);
        l1 = stof(&args[3]);
        h2 = stof(&args[4]);
        s2 = stof(&args[5]);
    }
    if argc > 6 {
        l2 = stof(&args[6]);
    }

    let hsl1 = Hsl::new(h1, s1, l1);
    let hsl2 = Hsl::new(h2, s2, l2);

    let hue_diff = ColorConverter::hue_difference(&hsl1, &hsl2);

    println!("{}", format_default(hue_diff as f64));
}

