//! Re-implementation of the parts of the `ColorSpace` C++ library that
//! `test13` exercises.

pub mod converter;
pub mod hsl;

pub use converter::ColorConverter;
pub use hsl::Hsl;

//! Small shims reproducing the C++ standard-library behaviour that the
//! original test relies on: `std::stof` parsing and `std::cout` formatting.

pub mod ostream;
pub mod stof;

